package com.procurement.goodsreceipt.entity;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity@Table(name="goods_receipt_attachments")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class GoodsReceiptAttachment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="grn_attachment_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="grn_id",nullable=false)private GoodsReceiptNote goodsReceiptNote;@Column(name="file_name",nullable=false)private String fileName;@Column(name="file_path",nullable=false,length=1000)private String filePath;@Column(name="file_type",nullable=false)private String fileType;@Column(name="uploaded_at",nullable=false)private LocalDateTime uploadedAt;@PrePersist void pre(){if(uploadedAt==null)uploadedAt=LocalDateTime.now();}}
